const rulesOf = (state: ParseState) => [...state].map(rule => (
  rule.type === RuleType.END ? { type: rule.type } : { type: rule.type, value: rule.value }
));

const snapshot = ({ grammar, inputs }: Case) => {
  const out: Record<string, unknown> = { grammar, steps: [] as unknown[] };
  const steps = out.steps as Record<string, unknown>[];
  let state: ParseState;
  try {
    state = GBNF(grammar);
  } catch (err) {
    out.error = `${(err as Error).name}: ${(err as Error).message}`;
    return out;
  }
  const graph = (state as unknown as { graph: Graph; }).graph;
  const pointersOf = (s: ParseState) => (s as unknown as { pointers: Pointers; }).pointers;
  out.print = graph.print();
  out.printColor = graph.print(undefined, true);
  out.printPointers = graph.print(pointersOf(state), false);
  out.initial = { rules: rulesOf(state), size: state.size, grammar: state.grammar };
  for (const input of inputs) {
    const step: Record<string, unknown> = { input };
    try {
      state = state.add(input);
      step.rules = rulesOf(state);
      step.size = state.size;
      step.print = graph.print(pointersOf(state), false);
    } catch (err) {
      const error = err as Error & { errorForMostRecentInput?: string; src?: string; };
      step.error = `${error.name}: ${error.message}`;
      step.message = error.message;
      if (error.errorForMostRecentInput !== undefined) {
        step.errorForMostRecentInput = error.errorForMostRecentInput;
        step.src = error.src;
      }
      steps.push(step);
      break;
    }
    steps.push(step);
  }
  return out;
};

const cases: Case[] = JSON.parse(readFileSync(process.argv[2], 'utf-8'));
writeFileSync(process.argv[3], JSON.stringify(cases.map(snapshot), null, 2));
void isRange;
void internals;

