// Dump the TypeScript port's behaviour for the shared set of cases.
//
// The graph is built by hand (exactly as `gbnf.ts` does) so that the debug
// `print()` output and the pointer set can be compared too; `ParseState` keeps
// both of those private.
import { readFileSync, writeFileSync } from 'node:fs';
import { Graph, Pointers, RuleStack } from '../ported_implementation/src/grammar-graph/graph.js';
import { ParseState } from '../ported_implementation/src/grammar-graph/parse-state.js';
import { RuleType, ValidInput } from '../ported_implementation/src/grammar-graph/types.js';
import { buildRuleStack } from '../ported_implementation/src/grammar-parser/build-rule-stack.js';
import { RulesBuilder } from '../ported_implementation/src/rules-builder/rules-builder.js';
import { GrammarParseError } from '../ported_implementation/src/utils/errors/grammar-parse-error.js';

interface Case { grammar: string; inputs: ValidInput[]; }

const buildGraph = (grammar: string): Graph => {
  const { rules, symbolIds } = new RulesBuilder(grammar);
  if (rules.length === 0) {
    throw new GrammarParseError(grammar, 0, 'No rules were found');
  }
  const rootId = symbolIds.get('root');
  const stackedRules: (RuleStack | undefined)[] = rules.map(rule => (
    rule !== undefined ? buildRuleStack(rule) : undefined
  ));
  return new Graph(grammar, stackedRules, rootId);
};

const rulesOf = (state: ParseState) => [...state].map(rule => (
  rule.type === RuleType.END ? { type: rule.type } : { type: rule.type, value: rule.value }
));

const snapshot = ({ grammar, inputs }: Case) => {
  const out: Record<string, unknown> = { grammar, steps: [] as unknown[] };
  const steps = out.steps as Record<string, unknown>[];
  let graph: Graph;
  let pointers: Pointers;
  try {
    graph = buildGraph(grammar);
    pointers = graph.add('');
  } catch (err) {
    out.error = `${(err as Error).name}: ${(err as Error).message}`;
    return out;
  }
  out.print = graph.print();
  out.printColor = graph.print(undefined, true);
  out.printPointers = graph.print(pointers, false);
  let state = new ParseState(graph, pointers);
  out.initial = { rules: rulesOf(state), size: state.size, grammar: state.grammar };
  for (const input of inputs) {
    const step: Record<string, unknown> = { input };
    try {
      pointers = graph.add(input, pointers);
      state = new ParseState(graph, pointers);
      step.rules = rulesOf(state);
      step.size = state.size;
      step.print = graph.print(pointers, false);
    } catch (err) {
      const error = err as Error & { errorForMostRecentInput?: string; src?: string; };
      step.error = `${error.name}: ${error.message}`;
      step.message = error.message;
      if (error.errorForMostRecentInput !== undefined) {
        step.errorForMostRecentInput = error.errorForMostRecentInput;
        step.src = error.src;
      }
      steps.push(step);
      break;
    }
    steps.push(step);
  }
  return out;
};

const cases: Case[] = JSON.parse(readFileSync(process.argv[2], 'utf-8'));
writeFileSync(process.argv[3], JSON.stringify(cases.map(snapshot), null, 2));

