cat > smoke.test.ts << 'EOF'
import { describe, expect, test } from 'vitest';
import GBNF, {
  GrammarParseError,
  InputParseError,
  isRange,
  ParseState,
  RuleType,
} from '../ported_implementation/src/index.js';

describe('public API', () => {
  test('default export, size, grammar, chaining', () => {
    const state = GBNF('root ::= "I like green eggs and ham"');
    expect(state).toBeInstanceOf(ParseState);
    expect(state.grammar).toEqual('root ::= "I like green eggs and ham"');
    expect(state.size).toEqual(1);
    const next = state.add('I li').add('ke gree');
    expect([...next]).toEqual([{ type: RuleType.CHAR, value: [110] }]);
  });

  test('code point and code point array input', () => {
    expect([...GBNF('root ::= "abc"').add(97).add([98])]).toEqual([{ type: 'char', value: [99] }]);
  });

  test('initial string', () => {
    expect([...GBNF('root ::= "abc"', 'ab')]).toEqual([{ type: 'char', value: [99] }]);
  });

  test('isRange', () => {
    expect(isRange([1, 2])).toBe(true);
    expect(isRange(1)).toBe(false);
    expect(isRange([1, 2, 3])).toBe(false);
  });

  test('errors', () => {
    expect(() => GBNF('root = "a"')).toThrow(GrammarParseError);
    expect(() => GBNF('root ::= "a"').add('b')).toThrow(InputParseError);
    const err = new InputParseError('z', 0, 'ba');
    expect(err).toBeInstanceOf(Error);
    expect(err.src).toEqual('baz');
    expect(err.errorForMostRecentInput).toEqual('Failed to parse input string:\n\nz\n^');
    expect(err.message).toEqual('Failed to parse input string:\n\nbaz\n  ^');
  });

  test('astral plane characters are single code points on both sides', () => {
    const state = GBNF('root ::= "\\U0001F600" | [\\U0001F601-\\U0001F64F]');
    expect([...state]).toEqual([
      { type: 'char', value: [0x1F600] },
      { type: 'char', value: [[0x1F601, 0x1F64F]] },
    ]);
    expect([...state.add('😀')]).toEqual([{ type: 'end' }]);
    expect([...state.add('😅')]).toEqual([{ type: 'end' }]);
  });
});
EOF
